pub fn column(allocator: mem.Allocator, s: []const u8, index: i32) ![]i16 {
    if (index < 1) return error.InvalidIndex;

    // Count rows: number of '\n' plus 1
    var row_count: usize = 1;
    for (s) |c| {
        if (c == u8('\n')) {
            row_count += 1;
        }
    }

    // Allocate result array
    var result = try allocator.alloc(i16, row_count);
    var r_idx: usize = 0; // position in result

    var current_row: usize = 1; // 1-based row index
    var current_col: i32 = 1;   // 1-based column index

    var i: usize = 0;
    while (i < s.len) {
        // Skip spaces
        while (i < s.len and s[i] == ' ') {
            i += 1;
        }
        if (i >= s.len) {
            // reached end of line
            break;
        }

        // Parse a number: find start and end
        var start = i;
        while (i < s.len and s[i] != ' ') {
            i += 1;
        }
        // Convert to i16
