const std = @import("std");
const mem = std.mem;

/// Returns the selected row of the matrix.
pub fn row(allocator: mem.Allocator, s: []const u8, index: i32) ![]i16 {
    if (index < 1) return error.InvalidIndex;

    // Find the start of the requested row (1-based)
    var row_start: usize = 0;
    var row_idx: i32 = 1; // current row number
    var i: usize = 0;

    while (i < s.len) {
        if (row_idx == index) break;
        if (s[i] == '\n') {
            row_idx += 1;
            row_start = i + 1;
        }
        i += 1;
    }

    // If the requested row was not found, error
    if (row_idx != index) {
        return error.InvalidIndex;
    }

    // Determine end of the row (newline or end of string)
    var row_end: usize = row_start;
    while (row_end < s.len and s[row_end] != '\n') {
        row_end += 1;
    }

    // Parse the line
    return parseNumbers(allocator, s[row_start..row_end]);
}

/// Parses a line (without newline) into a dynamic array of i16.
fn parseNumbers(allocator: mem.Allocator, line: []const u8) ![]i16 {
    // Count numbers
    var count: usize = 0;
    var i: usize = 0;
    while (i < line.len) {
        while (i < line.len and line[i] == ' ') i += 1;
        if (i < line.len) {
            count += 1;
            while (i < line.len and line[i] != ' ') i += 1;
        }
    }

    // Allocate result
    var nums = try allocator.alloc(i16, count);
    var idx: usize = 0;
    i = 0;
    while (i < line.len) {
        while (i < line.len and line[i] == ' ') i += 1;
        if (i < line.len) {
            var start = i;
            while (i < line.len and line[i] != ' ') i += 1;
            nums[idx] = try std.fmt.parseInt(i16, .{}.NumberBase.Decimal, line[start..i], 10);
            idx += 1;
        }
    }
    return nums;
}

/// Returns the selected column of the matrix.
pub fn column(allocator: mem.Allocator, s: []const u8, index: i32) ![]i16 {
    if (index < 1) return error.InvalidIndex;

    // Count rows (number of '\n' + 1)
    var row_count: usize = 1;
    for (s) |c| {
        if (c == u8('\n')) {
            row_count += 1;
        }
    }

    // Allocate result array
    var result = try allocator.alloc(i16, row_count);
    var r_idx: usize = 0; // position in result

    var current_row: usize = 1; // 1-based row index
    var current_col: i32 = 1;   // 1-based column index

    var i: usize = 0;
    while (i < s.len) {
        // Skip spaces
        while (i < s.len and s[i] == ' ') {
            i += 1;
        }
        if (i >= s.len) {
            break; // end of line
        }

        // Parse a number
        var start = i;
        while (i < s.len and s[i] != ' ') {
            i += 1;
        }
        const value = try std.fmt.parseInt(i16, .{}.NumberBase.Decimal, s[start..i], 10);

        // If this column matches the requested index, store it
        if (current_col == index) {
            result[r_idx] = value;
            r_idx += 1;
        }

        // Move to next column
        current_col += 1;

        // Check for newline to advance to next row
        if (i < s.len and s[i] == '\n') {
            current_row += 1;
            current_col = 1;
            i += 1; // skip newline
        }
    }

    return result;
}
