pub fn column(allocator: mem.Allocator, s: []const u8, index: i32) ![]i16 {
    if (index < 1) return error.InvalidIndex;

    // Count rows
    var row_count: usize = 1;
    for (s) |c| {
        if (c == u8('\n')) {
            row_count += 1;
        }
    }

    // Allocate result
    var result = try allocator.alloc(i16, row_count);
    var r_idx: usize = 0; // index into result

    var current_row: usize = 1; // row number we are processing (1-based)
    var current_col: i32 = 1; // column number within current row

    var i: usize = 0;
    while (i < s.len) {
        // Skip spaces
        while (i < s.len and s[i] == ' ') {
            i += 1;
        }
        if (i >= s.len) break; // end of line

        // Parse a number
        var start = i; // start of number
        while (i < s.len and s[i] != ' ') {
            i += 1;
        }
        // Convert substring to i16
        const num = try std.fmt.parseInt(i16, s[start..i], 10);

        // If this column matches requested index, store it
        if (current_col == index) {
            result[r_idx] = num;
            r_idx += 1;
        }

        // Increment column counter
        current_col += 1;

        // Check for newline to move to next row
        if (i < s.len and s[i] == '\n') {
            current_row += 1;
            current_col = 1;
            i += 1; // skip newline
        }
    }

    // If we reached end of string but not newline, still need to ensure we processed last number
    // The loop already handles numbers; after loop, we may have processed last number.

    // Ensure we have exactly row_count elements (should be)
    // If index is out of range for some rows, the tests will catch.

    return result;
}

