Let's rewrite column function:

```
pub fn column(allocator: mem.Allocator, s: []const u8, index: i32) ![]i16 {
    if (index < 1) return error.InvalidIndex;

    // Count rows: number of '\n' plus 1
    var row_count: usize = 1;
    for (s) |c| {
        if (c == u8('\n')) {
            row_count += 1;
        }
    }

    // Allocate result array
    var result = try allocator.alloc(i16, row_count);
    var r_idx: usize = 0; // position in result

    var current_row: usize = 1; // 1-based row index
    var current_col: i32 = 1;   // 1-based column index

    var i: usize = 0;
    while (i < s.len) {
        // Skip spaces
        while (i < s.len and s[i] == ' ') {
            i += 1;
        }
        if (i >= s.len) {
            // reached end of line
            break;
        }

        // Parse a number: find start and end
        var start = i;
        while (i < s.len and s[i] != ' ') {
            i += 1;
        }
        // Convert to i16
        const value = try std.fmt.parseInt(i16, s[start..i], 10);

        // If this column matches requested index, store it
        if (current_col == index) {
            result[r_idx] = value;
            r_idx += 1;
        }

        // Move to next column
        current_col += 1;

        // Check for newline to advance to next row
        if (i < s.len and s[i] == '\n') {
            current_row += 1;
            current_col = 1;
            i += 1; // skip the newline
        }
    }

    // If we exited loop because i == s.len, we may have processed the last number already.
    // Ensure we have exactly row_count elements; if index out of range for some rows,
    // the test will catch it.

    return result;
}
```

