```
pub fn row(allocator: mem.Allocator, s: []const u8, index: i32) ![]i16 {
    if (index < 1) return error.InvalidIndex;

    // Find the start of the requested row
    var row_start: usize = 0;
    var row_idx: i32 = 1; // current row number (1-based)
    var i: usize = 0;

    while (i < s.len) {
        if (row_idx == index) break;
        if (s[i] == '\n') {
            row_idx += 1;
            row_start = i + 1;
        }
        i += 1;
    }

    // If we didn't find the row, it's an invalid index
    if (row_idx != index) {
        return error.InvalidIndex;
    }

    // Determine end of the row (either newline or end of string)
    var row_end: usize = row_start;
    while (row_end < s.len and s[row_end] != '\n') {
        row_end += 1;
    }

    // Parse the line
    return parseNumbers(allocator, s[row_start..row_end]);
}
```

